mapper.insert:
INSERT INTO alert_message_active (id, summary, description, labels, start_at, end_at, last_at, state, rule_id, project_id, module_id, endpoint_id, asset_id, dc_id, hash_key, remark, severity_id) VALUES
( #{item.id}, #{item.summary}, #{item.description}, #{item.labels}, #{item.startAt}, #{item.endAt}, #{item.lastAt}, #{item.state}, #{item.ruleId}, #{item.projectId}, #{item.moduleId}, #{item.endpointId}, #{item.assetId}, #{item.dcId}, #{item.hashKey}, #{item.remark}, #{item.severityId} )
ON DUPLICATE KEY UPDATE id = VALUES(id), start_at = VALUES(start_at), last_at = VALUES(last_at), end_at = VALUES(end_at);

mapper.select:
SELECT am.*, ar.id as r_id , ar.name as r_name, ar.type as r_type, ar.trb_shot as r_trb_shot, p.id as p_id, p.name as p_name, m.id as m_id, m.name as m_name, e.id as e_id, e.name as e_name, ass.id as ass_id, ass.name as ass_name, alsc.id as alsc_id, alsc.name as alsc_name, alsc.color as alsc_color, dc.id as dc_id, dc.name as dc_name FROM
${params.tableName} am
(select * from alert_message_active union all select * from alert_message_history union all select * from alert_message_silence) am
LEFT JOIN alert_rule ar ON am.rule_id = ar.id LEFT JOIN monitor_project p on am.project_id = p.id LEFT JOIN monitor_module m on am.module_id = m.id LEFT JOIN monitor_endpoint e on am.endpoint_id = e.id LEFT JOIN asset_asset ass on am.asset_id = ass.id LEFT JOIN alert_severity_conf alsc on am.severity_id = alsc.id LEFT JOIN dc dc on am.dc_id = dc.id
locate(#{params.ruleName} , ar.name)
AND am.severity_id in
#{id}
AND locate(#{params.summary} , am.summary)
AND locate(#{params.description} , am.description)
AND am.id in
#{id}
AND am.state=#{params.state}
AND am.start_at >= #{params.startAt}
AND am.start_at <= #{params.endAt}
AND am.rule_id in
#{id}
AND am.project_id in
#{id}
AND am.module_id in
#{id}
AND am.endpoint_id in
#{id}
AND am.asset_id in
#{id}
AND am.dc_id in
#{id}
AND locate(#{params.labels},am.labels)
AND locate(#{params.endpointName},e.name)
AND locate(#{params.assetName},ass.name)
AND locate(#{params.asset},ass.name)
ORDER BY am.id

SELECT ${columnId} AS id, count(1) AS num FROM
${params.tableName} am
(select * from alert_message_active union all select * from alert_message_history union all select * from alert_message_silence) am
LEFT JOIN alert_rule ar ON am.rule_id = ar.id LEFT JOIN monitor_project p on am.project_id = p.id LEFT JOIN monitor_module m on am.module_id = m.id LEFT JOIN monitor_endpoint e on am.endpoint_id = e.id LEFT JOIN asset_asset ass on am.asset_id = ass.id LEFT JOIN alert_severity_conf alsc on am.severity_id = alsc.id LEFT JOIN dc dc on am.dc_id = dc.id
${columnId} is not null
AND locate(#{params.ruleName},ar.name)
AND am.severity_id in
#{id}
AND locate(#{params.summary},am.summary)
AND locate(#{params.description},am.description)
AND am.id in
#{id}
AND am.state=#{params.state}
AND am.start_at >= #{params.startAt}
AND am.start_at <= #{params.endAt}
AND am.rule_id in
#{id}
AND am.project_id in
#{id}
AND am.module_id in
#{id}
AND am.endpoint_id in
#{id}
AND am.asset_id in
#{id}
AND am.dc_id in
#{id}
AND locate(#{params.labels}, am.labels)
AND locate(#{params.endpointName},e.name )
AND locate(#{params.assetName},ass.name)
AND locate(#{params.asset},ass.name)
GROUP BY ${columnId} ORDER BY num DESC
